param([int]$Port=3100)
$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$out=Join-Path $root 'evidence/governance/copilot-v1.2/p9/instrumentation/runtime';New-Item -ItemType Directory -Path $out -Force|Out-Null
$preload=Join-Path $root 'scripts/basic-diagnostic-preload.cjs';$telemetry=Join-Path $out 'server-telemetry.jsonl';$tracePattern=Join-Path $out 'node-trace-${pid}.json';$env:PORT="$Port";$env:AGM_DIAGNOSTIC_TELEMETRY_PATH=$telemetry;$env:NODE_OPTIONS="--require=$preload --trace-event-categories=v8,gc,node.perf --trace-event-file-pattern=$tracePattern"
$apiRoot=Join-Path $root 'apps/api';$dist=Join-Path $apiRoot 'dist/main.js';if(Test-Path $dist){$exe='node.exe';$arguments=@('dist/main.js');$launchMode='COMPILED_DIST'}else{$exe='pnpm.cmd';$arguments=@('exec','ts-node','src/main.ts');$launchMode='TS_NODE_EXISTING_DEPENDENCY'}
$process=Start-Process $exe -ArgumentList $arguments -WorkingDirectory $apiRoot -RedirectStandardOutput (Join-Path $out 'isolated-api.stdout.log') -RedirectStandardError (Join-Path $out 'isolated-api.stderr.log') -WindowStyle Hidden -PassThru
[ordered]@{contract='agm-basic-isolated-diagnostic-runtime.v2';pid=$process.Id;port=$Port;startedAt=(Get-Date).ToUniversalTime().ToString('o');telemetryPath=$telemetry;launchMode=$launchMode;nodeOptions='DIAGNOSTIC_PRELOAD_GC_EVENT_LOOP_REQUEST_CORRELATION';production=$false;functionalChange=$false;basicSourceModified=$false}|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $out 'isolated-runtime-custody.json') -Encoding utf8
Write-Output "ISOLATED BASIC DIAGNOSTIC RUNTIME - STARTED PID $($process.Id) PORT $Port"
